# model-registry-config.yaml
# 边缘端模型版本管理（MLflow 格式）
apiVersion: v1
kind: ConfigMap
metadata:
  name: triton-model-config
  namespace: edge-ai
data:
  # Triton 模型配置文件
  config.pbtxt: |
    name: "edge_classifier"
    platform: "onnxruntime_onnx"
    max_batch_size: 8

    input [
      {
        name: "input"
        data_type: TYPE_FP32
        dims: [3, 224, 224]
      }
    ]

    output [
      {
        name: "output"
        data_type: TYPE_FP32
        dims: [1000]
      }
    ]

    # 实例组配置（CPU 推理）
    instance_group [
      {
        kind: KIND_CPU
        count: 2
      }
    ]

    # 动态批处理
    dynamic_batching {
      preferred_batch_size: [4, 8]
      max_queue_delay_microseconds: 1000
    }

    # 模型预热
    model_warmup [
      {
        name: "warmup"
        batch_size: 1
        inputs {
          key: "input"
          value: {
            data_type: TYPE_FP32
            dims: [3, 224, 224]
            zero_data: true
          }
        }
      }
    ]
